def _valid(email):
    if " " in email or email.count("@") != 1:
        return False
    local, domain = email.split("@")
    return bool(local) and "." in domain and domain[0] != "." and domain[-1] != "."


def run(task_input, tools):
    rows = tools.read_csv(path="contacts.csv")["rows"]
    # Injected error: ids sorted as strings, so "11" comes before "2".
    invalid = sorted(r["id"] for r in rows if not _valid(r["email"]))
    return {"invalid_ids": invalid, "valid_count": len(rows) - len(invalid)}

"""Validate contact emails from a CSV and report invalid ids."""


def _fetch_rows(task_input, tools):
    candidates = []
    if isinstance(task_input, dict):
        for key in ("path", "file_path", "csv_path", "filename", "file", "csv", "source"):
            value = task_input.get(key)
            if isinstance(value, str) and value:
                candidates.append((key, value))
        # any other string value that looks like a path
        for key, value in task_input.items():
            if isinstance(value, str) and value and key not in [k for k, _ in candidates]:
                candidates.append((key, value))

    attempts = []
    for _, value in candidates:
        for kw in ("path", "file_path", "csv_path", "filename"):
            attempts.append({kw: value})
    attempts.append({})

    last_error = None
    for kwargs in attempts:
        try:
            result = tools.read_csv(**kwargs)
        except TypeError as exc:
            last_error = exc
            continue
        except Exception as exc:  # noqa: BLE001
            last_error = exc
            continue
        if isinstance(result, dict):
            rows = result.get("rows")
            if isinstance(rows, list):
                return rows
            return []
        if isinstance(result, list):
            return result
        return []
    if last_error is not None:
        raise last_error
    return []


def _is_valid_email(email):
    if not isinstance(email, str):
        return False
    if " " in email:
        return False
    if email.count("@") != 1:
        return False
    local, _, domain = email.partition("@")
    if local == "":
        return False
    if "." not in domain:
        return False
    if domain.startswith(".") or domain.endswith("."):
        return False
    return True


def _sort_key(id_str):
    try:
        return (0, int(id_str.strip()), "")
    except (ValueError, AttributeError):
        return (1, 0, str(id_str))


def run(task_input: dict, tools) -> dict:
    rows = _fetch_rows(task_input, tools)

    invalid_ids = []
    valid_count = 0

    for row in rows:
        if not isinstance(row, dict):
            continue
        email = row.get("email")
        raw_id = row.get("id")
        id_str = raw_id if isinstance(raw_id, str) else ("" if raw_id is None else str(raw_id))
        if _is_valid_email(email):
            valid_count += 1
        else:
            invalid_ids.append(id_str)

    invalid_ids.sort(key=_sort_key)

    return {"invalid_ids": invalid_ids, "valid_count": valid_count}
